questions.content:
现有5名学生（张、王、李、赵、周）的语数英三门成绩。请编写程序，计算每个学生的总成绩，以及小组的各科总成绩和平均成绩。
数据如下：
张：{88, 70, 90}
王：{80, 80, 60}
李：{89, 60, 85}
赵：{80, 75, 78}
周：{70, 80, 80}

questions.answer:
#include <stdio.h>

int main() {
    // 定义二维数组存储成绩，5行3列
    // 列0: 语文, 列1: 数学, 列2: 英语
    int scores[5][3] = {
        {88, 70, 90},
        {80, 80, 60},
        {89, 60, 85},
        {80, 75, 78},
        {70, 80, 80}
    };

    char *names[] = {"张同学", "王同学", "李同学", "赵同学", "周同学"};
    int studentSum;
    int subjectSum[3] = {0, 0, 0}; // 存储各科总分
    int i, j;

    // 计算每个学生的总成绩
    for (i = 0; i < 5; i++) {
        studentSum = 0;
        for (j = 0; j < 3; j++) {
            studentSum += scores[i][j];
            subjectSum[j] += scores[i][j]; // 累加科目的总分
        }
        printf("%s的总成绩: %d\n", names[i], studentSum);
    }

    printf("-------------------\n");

    // 计算并输出各科统计数据
    char *subjects[] = {"语文", "数学", "英语"};
    for (j = 0; j < 3; j++) {
        printf("%s总成绩: %d, 平均分: %.2f\n", 
               subjects[j], 
               subjectSum[j], 
               subjectSum[j] / 5.0);
    }

    return 0;
}

