#include <stdio.h>

// 循环方法
void decimalToOctalLoop(int n) {
    int octalNum[100];
    int i = 0;
    if (n == 0) {
        printf("0");
        return;
    }
    while (n > 0) {
        octalNum[i] = n % 8;
        n = n / 8;
        i++;
    }
    for (int j = i - 1; j >= 0; j--)
        printf("%d", octalNum[j]);
}

// 递归方法
void decimalToOctalRecursive(int n) {
    if (n > 0) {
        decimalToOctalRecursive(n / 8);
        printf("%d", n % 8);
    }
}

int main() {
    int num;
    printf("请输入一个十进制数: ");
    scanf("%d", &num);

    printf("循环方式输出八进制: ");
    decimalToOctalLoop(num);
    printf("\n");

    printf("递归方式输出八进制: ");
    if (num == 0) printf("0");
    else decimalToOctalRecursive(num);
    printf("\n");

    return 0;
}

