// 定义宏 DESC，注释掉这行则执行从小到大排序
#define DESC

int main() {
    int arr[10] = {12, 5, 8, 9, 1, 3, 7, 10, 4, 6};
    int i, j, temp;
    int n = 10;

    // 冒泡排序
    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            // 使用条件编译决定排序方向
#ifdef DESC
            // 从大到小：如果前一个小于后一个，则交换
            if (arr[j] < arr[j + 1])
#else
            // 从小到大：如果前一个大于后一个，则交换
            if (arr[j] > arr[j + 1])
#endif
            {
                temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    // 输出结果
    printf("排序结果: ");
    for (i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

