    rewind(fp);
    pos = ftell(fp);
    printf("当前位置: %ld\n", pos);

    // 2. 移动指针：从开头向后偏移6个字节
    fseek(fp, 6, SEEK_SET);
    pos = ftell(fp);
    printf("移动后位置: %ld\n", pos);

    // 3. 读取剩余内容
    fgets(buf, sizeof(buf), fp);
    printf("读取内容: %s\n", buf);

    fclose(fp);
    return 0;
}

